  flavorDataProvider.getFlavorData(
    transferable,
    "application/x-moz-file-promise"
  );
  await secondWritePromise;
  Assert.equal(
    await IOUtils.readUTF8(tempFile.path),
    fileContent,
    "existing file should not be overwritten"
  );
  Assert.equal(
    await IOUtils.readUTF8(numberedPath),
    fileContent,
